export const DHT11_OKU_SRC = "// sketch: dht_oku\n#include <DHT.h>\n\n#define DHT_PIN 5\n#define DHT_TIP DHT11        // DHT11 kullanıyorsan burayı DHT11 yap\n\nDHT dht(DHT_PIN, DHT_TIP);\n\nvoid setup() {\n  Serial.begin(9600);\n  dht.begin();\n}\n\nvoid loop() {\n  delay(2000);                          // okumalar arası en az 2 sn\n  float nem = dht.readHumidity();\n  float sicaklik = dht.readTemperature();   // santigrat\n\n  if (isnan(nem) || isnan(sicaklik)) {\n    Serial.println(\"Okuma hatasi\");\n    return;\n  }\n\n  Serial.print(\"Sicaklik: \");\n  Serial.print(sicaklik, 1);\n  Serial.print(\" C  Nem: \");\n  Serial.print(nem, 1);\n  Serial.println(\" %\");\n}\n"
